wp:postmeta.wp:meta_value:
/* ============================================
   SAGE About Us - Modern Responsive Design
   Created for SAGE - Shastry Associates Global Enterprises
   ============================================ */

/* === CSS Reset & Variables === */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  /* Brand Colors */
  --primary-color: #f96a30;
  --primary-dark: #e85a20;
  --primary-light: #ff9966;
  --secondary-color: #1a1a2e;
  --accent-color: #16213e;

  /* Text Colors */
  --text-dark: #1a1a2e;
  --text-medium: #2c3e50;
  --text-light: #555;
  --text-muted: #888;

  /* Background Colors */
  --bg-white: #ffffff;
  --bg-light: #f8f9fa;
  --bg-lighter: #fafbfc;
  --bg-gradient: linear-gradient(135deg, #f96a30 0%, #e85a20 100%);

  /* Spacing */
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-xxl: 5rem;

  /* Shadows */
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.12);
  --shadow-xl: 0 12px 32px rgba(0, 0, 0, 0.15);

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  /* Transitions */
  --transition-fast: 0.2s ease;
  --transition-normal: 0.3s ease;
  --transition-slow: 0.5s ease;
}

/* === Base Styles === */
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--text-dark);
  line-height: 1.7;
  background: var(--bg-white);
  overflow-x: hidden;
  opacity: 0;
  transition: opacity 0.5s ease;
}

body.loaded {
  opacity: 1;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

/* === Hero Section === */
.about-hero {
  position: relative;
  height: 100vh;
  min-height: 600px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  will-change: transform;
}

.hero-background {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0f0f1e 0%, #1a1a2e 50%, #16213e 100%);
  z-index: 1;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: 
    radial-gradient(circle at 20% 50%, rgba(249, 106, 48, 0.15) 0%, transparent 50%),
    radial-gradient(circle at 80% 50%, rgba(249, 106, 48, 0.1) 0%, transparent 50%);
  z-index: 2;
}

/* Animated Background Shapes */
.animated-shapes {
  position: absolute;
  inset: 0;
  z-index: 2;
  overflow: hidden;
}

.shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.3;
  animation: float 20s infinite ease-in-out;
}

.shape-1 {
  width: 400px;
  height: 400px;
  background: linear-gradient(135deg, var(--primary-color), var(--primary-light));
  top: -100px;
  left: -100px;
  animation-delay: 0s;
}

.shape-2 {
  width: 300px;
  height: 300px;
  background: linear-gradient(135deg, var(--primary-light), var(--primary-color));
  bottom: -150px;
  right: -100px;
  animation-delay: 5s;
}

.shape-3 {
  width: 250px;
  height: 250px;
  background: linear-gradient(135deg, var(--primary-color), #ff6b35);
  top: 50%;
  right: 10%;
  animation-delay: 10s;
}

@keyframes float {
  0%, 100% { transform: translate(0, 0) rotate(0deg); }
  25% { transform: translate(50px, 50px) rotate(90deg); }
  50% { transform: translate(0, 100px) rotate(180deg); }
  75% { transform: translate(-50px, 50px) rotate(270deg); }
}

/* Hero Content */
.hero-content {
  position: relative;
  z-index: 10;
  text-align: center;
  color: var(--bg-white);
  max-width: 900px;
  padding: var(--spacing-lg);
  animation: fadeInUp 1s ease;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  padding: 0.6rem 1.5rem;
  border-radius: 50px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: var(--spacing-md);
  animation: fadeIn 1s ease 0.3s both;
}

.hero-badge i {
  color: var(--primary-color);
}

.hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 900;
  line-height: 1.1;
  margin-bottom: var(--spacing-md);
  animation: fadeIn 1s ease 0.5s both;
}

.title-line {
  display: block;
}

.gradient-text {
  background: linear-gradient(135deg, var(--primary-color), var(--primary-light));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.3rem);
  color: rgba(255, 255, 255, 0.8);
  max-width: 600px;
  margin: 0 auto var(--spacing-xl);
  animation: fadeIn 1s ease 0.7s both;
}

.scroll-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 50px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  cursor: pointer;
  transition: var(--transition-normal);
  animation: bounce 2s infinite, fadeIn 1s ease 1s both;
}

.scroll-indicator:hover {
  background: rgba(249, 106, 48, 0.2);
  border-color: var(--primary-color);
  transform: translateY(-5px);
}

.scroll-indicator i {
  color: var(--primary-color);
  font-size: 1.2rem;
}

@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(10px); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* === Main About Section === */
.about-main {
  background: var(--bg-white);
  position: relative;
  z-index: 10;
}

/* Section Labels */
.section-label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--primary-color);
  font-weight: 600;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: var(--spacing-sm);
}

.label-dot {
  width: 8px;
  height: 8px;
  background: var(--primary-color);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.2); opacity: 0.7; }
}

/* Section Titles */
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 800;
  color: var(--text-dark);
  margin-bottom: var(--spacing-md);
  line-height: 1.2;
}

.section-title .highlight {
  color: var(--primary-color);
  position: relative;
}

.section-description {
  font-size: 1.1rem;
  color: var(--text-light);
  max-width: 600px;
  margin-bottom: var(--spacing-xl);
}

/* === Introduction Section === */
.about-intro {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xxl);
  align-items: center;
  padding: var(--spacing-xxl) 0;
}

/* Intro Image */
.intro-image {
  position: relative;
  opacity: 0;
  transform: translateX(-50px);
  transition: all 0.8s ease;
}

.intro-image.animate-in {
  opacity: 1;
  transform: translateX(0);
}

.image-wrapper {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
}

.image-wrapper img {
  width: 100%;
  height: 500px;
  object-fit: cover;
  display: block;
  transition: transform 0.5s ease;
}

.image-wrapper:hover img {
  transform: scale(1.05);
}

.image-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 0%, rgba(0, 0, 0, 0.3) 100%);
  pointer-events: none;
}

.image-badge {
  position: absolute;
  bottom: var(--spacing-lg);
  left: var(--spacing-lg);
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  box-shadow: var(--shadow-md);
}

.image-badge i {
  color: var(--primary-color);
  font-size: 1.5rem;
}

.image-badge span {
  font-weight: 600;
  color: var(--text-dark);
}

/* Floating Stats */
.floating-stats {
  position: absolute;
  top: -20px;
  right: -20px;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.stat-card {
  background: var(--bg-white);
  padding: 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 1rem;
  min-width: 180px;
  transition: transform 0.3s ease;
}

.stat-card:hover {
  transform: translateY(-5px);
}

.stat-icon {
  width: 50px;
  height: 50px;
  background: var(--bg-gradient);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.stat-icon i {
  color: var(--bg-white);
  font-size: 1.5rem;
}

.stat-info h3 {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--text-dark);
  margin: 0;
}

.stat-info p {
  font-size: 0.85rem;
  color: var(--text-light);
  margin: 0;
}

/* Intro Content */
.intro-content {
  opacity: 0;
  transform: translateX(50px);
  transition: all 0.8s ease;
}

.intro-content.animate-in {
  opacity: 1;
  transform: translateX(0);
}

.intro-text {
  margin-top: var(--spacing-lg);
}

.intro-text p {
  margin-bottom: var(--spacing-md);
  color: var(--text-medium);
  font-size: 1.05rem;
  line-height: 1.8;
}

.lead-text {
  font-size: 1.15rem !important;
  font-weight: 500;
  color: var(--text-dark) !important;
}

.highlight-box {
  background: linear-gradient(135deg, #fff5f0 0%, #ffe6d9 100%);
  border-left: 4px solid var(--primary-color);
  padding: var(--spacing-md);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-top: var(--spacing-lg);
}

.highlight-box i {
  color: var(--primary-color);
  font-size: 1.5rem;
  flex-shrink: 0;
  margin-top: 0.25rem;
}

/* === Expertise Section === */
.expertise-section {
  padding: var(--spacing-xxl) 0;
  background: var(--bg-light);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto var(--spacing-xl);
}

.expertise-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.expertise-card {
  background: var(--bg-white);
  padding: var(--spacing-xl);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
  opacity: 0;
  transform: translateY(30px);
}

.expertise-card.animate-in {
  opacity: 1;
  transform: translateY(0);
}

.expertise-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--bg-gradient);
  transform: scaleX(0);
  transition: transform 0.3s ease;
}

.expertise-card:hover {
  transform: translateY(-10px);
  box-shadow: var(--shadow-xl);
}

.expertise-card:hover::before {
  transform: scaleX(1);
}

.card-icon {
  width: 70px;
  height: 70px;
  background: linear-gradient(135deg, #fff5f0, #ffe6d9);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--spacing-md);
  transition: all 0.3s ease;
}

.expertise-card:hover .card-icon {
  background: var(--bg-gradient);
  transform: rotate(5deg) scale(1.1);
}

.card-icon i {
  font-size: 2rem;
  color: var(--primary-color);
  transition: color 0.3s ease;
}

.expertise-card:hover .card-icon i {
  color: var(--bg-white);
}

.expertise-card h3 {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: var(--spacing-sm);
}

.expertise-card p {
  color: var(--text-light);
  line-height: 1.7;
  margin-bottom: var(--spacing-md);
}

.card-footer {
  margin-top: auto;
}

.card-tag {
  display: inline-block;
  background: #e8f5e9;
  color: #2e7d32;
  padding: 0.4rem 1rem;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
}

/* === Services Section === */
.services-section {
  padding: var(--spacing-xxl) 0;
}

.services-grid {
  display: grid;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.service-item {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: var(--spacing-lg);
  padding: var(--spacing-xl);
  background: var(--bg-lighter);
  border-radius: var(--radius-lg);
  border: 2px solid transparent;
  transition: all 0.3s ease;
  opacity: 0;
  transform: translateX(-30px);
}

.service-item.animate-in {
  opacity: 1;
  transform: translateX(0);
}

.service-item:hover {
  background: var(--bg-white);
  border-color: var(--primary-color);
  box-shadow: var(--shadow-md);
  transform: translateX(10px);
}

.service-number {
  font-family: 'Playfair Display', serif;
  font-size: 3rem;
  font-weight: 800;
  color: var(--primary-color);
  opacity: 0.2;
  line-height: 1;
  transition: opacity 0.3s ease;
}

.service-item:hover .service-number {
  opacity: 1;
}

.service-content h3 {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: var(--spacing-sm);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.service-content h3 i {
  color: var(--primary-color);
}

.service-content p {
  color: var(--text-light);
  line-height: 1.7;
}

/* === Values Section === */
.values-section {
  padding: var(--spacing-xxl) 0;
  background: var(--bg-light);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xxl);
  align-items: center;
}

.values-list {
  display: grid;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.value-item {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-md);
  opacity: 0;
  transform: translateX(-30px);
  transition: all 0.5s ease;
}

.value-item.animate-in {
  opacity: 1;
  transform: translateX(0);
}

.value-icon {
  width: 60px;
  height: 60px;
  background: var(--bg-gradient);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.3s ease;
}

.value-item:hover .value-icon {
  transform: scale(1.1) rotate(5deg);
}

.value-icon i {
  color: var(--bg-white);
  font-size: 1.5rem;
}

.value-text h4 {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 0.5rem;
}

.value-text p {
  color: var(--text-light);
  line-height: 1.7;
}

/* Values Visual */
.values-visual {
  position: relative;
}

.visual-card {
  background: var(--bg-white);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  position: relative;
  overflow: hidden;
}

.visual-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: var(--bg-gradient);
}

.visual-content {
  padding: var(--spacing-lg);
}

.visual-content i {
  color: var(--primary-color);
  font-size: 3rem;
  opacity: 0.2;
  margin-bottom: var(--spacing-md);
}

.quote-text {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text-medium);
  line-height: 1.8;
  margin-bottom: var(--spacing-md);
}

.quote-author {
  color: var(--text-light);
  font-size: 0.95rem;
}

.quote-author strong {
  color: var(--primary-color);
}

/* === CTA Section === */
.cta-section {
  padding: var(--spacing-xxl) 0;
  background: linear-gradient(135deg, var(--secondary-color) 0%, var(--accent-color) 100%);
  border-radius: var(--radius-xl);
  margin: var(--spacing-xxl) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: 
    radial-gradient(circle at 30% 50%, rgba(249, 106, 48, 0.1) 0%, transparent 50%),
    radial-gradient(circle at 70% 50%, rgba(249, 106, 48, 0.05) 0%, transparent 50%);
  pointer-events: none;
}

.cta-content {
  position: relative;
  z-index: 2;
  padding: var(--spacing-xl);
}

.cta-content h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--bg-white);
  margin-bottom: var(--spacing-sm);
}

.cta-content p {
  font-size: 1.2rem;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: var(--spacing-xl);
}

.cta-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 2rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  text-decoration: none;
  transition: all 0.3s ease;
  cursor: pointer;
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--bg-gradient);
  color: var(--bg-white);
  box-shadow: 0 4px 16px rgba(249, 106, 48, 0.3);
}

.btn-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 24px rgba(249, 106, 48, 0.4);
}

.btn-secondary {
  background: transparent;
  color: var(--bg-white);
  border-color: rgba(255, 255, 255, 0.3);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--bg-white);
  transform: translateY(-3px);
}

/* === Responsive Design === */

/* Tablet (768px - 1024px) */
@media (max-width: 1024px) {
  .about-intro,
  .values-section {
    grid-template-columns: 1fr;
    gap: var(--spacing-xl);
  }

  .floating-stats {
    position: static;
    flex-direction: row;
    margin-top: var(--spacing-md);
  }

  .expertise-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Mobile (320px - 767px) */
@media (max-width: 767px) {
  .container {
    padding: 0 var(--spacing-md);
  }

  .about-hero {
    height: 80vh;
    min-height: 500px;
  }

  .hero-title {
    font-size: 2.5rem;
  }

  .section-title {
    font-size: 2rem;
  }

  .about-intro,
  .values-section {
    padding: var(--spacing-xl) 0;
  }

  .expertise-grid {
    grid-template-columns: 1fr;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .service-number {
    font-size: 2rem;
  }

  .floating-stats {
    flex-direction: column;
  }

  .stat-card {
    width: 100%;
  }

  .cta-buttons {
    flex-direction: column;
  }

  .btn {
    width: 100%;
    justify-content: center;
  }

  .image-wrapper img {
    height: 350px;
  }

  .values-visual {
    order: -1;
  }
}

/* === Accessibility === */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Focus Styles */
.btn:focus,
.scroll-indicator:focus {
  outline: 3px solid var(--primary-color);
  outline-offset: 3px;
}

/* === Print Styles === */
@media print {
  .hero-background,
  .animated-shapes,
  .scroll-indicator,
  .cta-section,
  .btn {
    display: none !important;
  }

  .about-hero {
    height: auto;
    min-height: auto;
    page-break-after: always;
  }

  .expertise-card,
  .service-item,
  .value-item {
    break-inside: avoid;
  }
}

/* Reset */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Marquee Container */
.event-marquee {
  width: 100%;
  height: 52px;
  background: linear-gradient(90deg, #0b1c2d, #112e45);
  color: #ffffff;
  text-decoration: none;
  display: flex;
  align-items: center;
  overflow: hidden;
  position: relative;
  font-family: "Segoe UI", system-ui, sans-serif;
  box-shadow: 0 4px 10px rgba(0,0,0,0.15);
}

/* Marquee Track */
.marquee-track {
  display: flex;
  width: max-content;
  animation: marquee-scroll 22s linear infinite;
}

/* Pause on hover */
.event-marquee:hover .marquee-track {
  animation-play-state: paused;
}

/* Marquee Text */
.marquee-track span {
  white-space: nowrap;
  padding-right: 60px;
  font-size: 15px;
  letter-spacing: 0.3px;
}

/* Highlight CTA */
.marquee-track em {
  color: #ffd166;
  font-style: normal;
  font-weight: 600;
  margin-left: 6px;
}

/* Animation */
@keyframes marquee-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* Responsive Tweaks */
@media (max-width: 768px) {
  .event-marquee {
    height: 48px;
  }

  .marquee-track span {
    font-size: 14px;
  }

  .marquee-track {
    animation-duration: 28s;
  }
}

@media (max-width: 480px) {
  .marquee-track span {
    font-size: 13px;
  }
}

