.events-list {
  max-width: 1200px;
  margin: 50px auto;
  padding: 0 20px;
  font-family: "Poppins", sans-serif;
}

.section-title {
  font-size: 2.2rem;
  text-align: center;
  margin-bottom: 40px;
  color: #222;
}

/* Event box container */
.event-item {
  display: flex;
  align-items: center;
  background: #fff;
  border-radius: 14px;
  margin-bottom: 35px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.event-item:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0,0,0,0.12);
}

/* Event image (left side) */
.event-img {
  width: 40%;
  height: 100%;
  object-fit: cover;
}

/* Event details (right side) */
.event-content {
  padding: 25px;
  width: 60%;
  text-align: left;
}

.event-title {
  font-size: 1.5rem;
  color: #333;
  margin-bottom: 8px;
}

.event-meta {
  font-size: 0.95rem;
  color: #666;
  margin-bottom: 12px;
}

.event-desc {
  font-size: 1rem;
  color: #555;
  line-height: 1.6;
  margin-bottom: 20px;
}

.btn {
  display: inline-block;
  background: #0073e6;
  color: #fff;
  padding: 10px 20px;
  border-radius: 8px;
  text-decoration: none;
  transition: background 0.3s ease;
}

.btn:hover {
  background: #005bb5;
}

/* Responsive for tablets and mobiles */
@media (max-width: 768px) {
  .event-item {
    flex-direction: column;
    text-align: center;
  }

  .event-img {
    width: 100%;
    height: 220px;
  }

  .event-content {
    width: 100%;
    padding: 20px;
  }
}

.events-list {
  max-width: 1200px;
  margin: 50px auto;
  padding: 0 20px;
  font-family: "Poppins", sans-serif;
}

.section-title {
  font-size: 2.2rem;
  text-align: center;
  margin-bottom: 40px;
  color: #222;
}

/* Event card */
.event-item {
  display: flex;
  align-items: stretch; /* Changed from center to stretch for consistent height */
  background: #fff;
  border-radius: 14px;
  border-style: solid;
  border-color: #222;
  border-width: 0.1px;
  margin-bottom: 25px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  position: relative; /* Added for status badge positioning */
  min-height: 290px; /* Fixed minimum height for consistency */
}

.event-item:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0,0,0,0.12);
}

/* Status Badge */
.status-badge {
  position: absolute;
  top: 15px;
  right: 15px;
  padding: 5px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  z-index: 10;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.status-upcoming {
  background: linear-gradient(135deg, #4CAF50, #45a049);
  color: white;
}

.status-completed {
  background: linear-gradient(135deg, #757575, #616161);
  color: white;
}

/* Alternative: If you prefer simpler solid colors */
/*
.status-upcoming {
  background: #4CAF50;
  color: white;
}

.status-completed {
  background: #757575;
  color: white;
}
*/

/* Event image - perfect square frame */
.event-img {
  width: 250px;
  height: 250px;
  object-fit: cover;
  object-position: center;
  border-radius: 12px;
  margin: 20px;
  background: #f3f3f3;
  flex-shrink: 0; /* Prevents image from shrinking */
  display: block;
}

/* Event content */
.event-content {
  flex: 1;
  padding: 20px 25px;
}

.event-title {
  font-size: 1.5rem;
  color: #333;
  margin-bottom: 8px;
}

.event-meta {
  font-size: 0.95rem;
  color: #666;
  margin-bottom: 12px;
}

.event-meta i {
  margin-right: 5px;
  color: #f96a30;
}

.event-desc {
  font-size: 1rem;
  color: #555;
  line-height: 1.6;
  margin-bottom: 20px;
}

.btn {
  display: inline-block;
  background: #f96a30;
  color: #fff;
  padding: 10px 20px;
  border-radius: 8px;
  text-decoration: none;
  transition: background 0.3s ease;
}

.btn:hover {
  background: #e65b21;
}

/* Responsive */
@media (max-width: 768px) {
  .event-item {
    flex-direction: column;
    text-align: center;
  }
  .event-img {
    width: 200px;
    height: 200px;
    margin: 20px auto 15px;
    flex-shrink: 0;
  }
  .event-content {
    width: 100%;
    padding: 15px;
  }
}

