  max-width: 1200px;
  margin: 50px auto;
  padding: 0 20px;
  font-family: "Poppins", sans-serif;
}

.section-title {
  font-size: 2.2rem;
  text-align: center;
  margin-bottom: 40px;
  color: #222;
}

/* Event box container */
.event-item {
  display: flex;
  align-items: center;
  background: #fff;
  border-radius: 14px;
  margin-bottom: 35px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.event-item:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0,0,0,0.12);
}

/* Event image (left side) */
.event-img {
  width: 40%;
  height: 100%;
  object-fit: cover;
}

/* Event details (right side) */
.event-content {
  padding: 25px;
  width: 60%;
  text-align: left;
}

.event-title {
  font-size: 1.5rem;
  color: #333;
  margin-bottom: 8px;
}

.event-meta {
  font-size: 0.95rem;
  color: #666;
  margin-bottom: 12px;
}

.event-desc {
  font-size: 1rem;
  color: #555;
  line-height: 1.6;
  margin-bottom: 20px;
}

.btn {
  display: inline-block;
  background: #0073e6;
  color: #fff;
  padding: 10px 20px;
  border-radius: 8px;
  text-decoration: none;
  transition: background 0.3s ease;
}

.btn:hover {
  background: #005bb5;
}

/* Responsive for tablets and mobiles */
@media (max-width: 768px) {
  .event-item {
    flex-direction: column;
    text-align: center;
  }

  .event-img {
    width: 100%;
    height: 220px;
  }

  .event-content {
    width: 100%;
    padding: 20px;
  }
}
