  padding-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.sage-info-card h4 i {
  color: #f96a30;
}

.sage-info-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid #ddd;
