/* === Agenda Tab - Timeline Design === */
.sage-timeline-wrapper {
  position: relative;
  padding-left: 40px;
  margin-top: 30px;
}

.sage-timeline-wrapper::before {
  content: '';
  position: absolute;
  left: 8px;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(180deg, #f96a30, #ff9966);
}

.sage-timeline-item {
  position: relative;
  margin-bottom: 30px;
  opacity: 0;
  transform: translateY(30px);
  transition: all 0.5s ease;
}

.sage-timeline-item.sage-aos-animate {
  opacity: 1;
  transform: translateY(0);
}

.sage-timeline-item::before {
  content: '';
  position: absolute;
  left: -36px;
  top: 8px;
  width: 15px;
  height: 15px;
  background: white;
  border: 3px solid #f96a30;
  border-radius: 50%;
  box-shadow: 0 0 0 4px rgba(249, 106, 48, 0.1);
