<script>
// Run script only after the HTML is fully loaded
document.addEventListener('DOMContentLoaded', function() {
  (function() {
    'use strict';

    // Tab Switching Logic
    const tabButtons = document.querySelectorAll('.sage-tab-btn');
    const tabContents = document.querySelectorAll('.sage-tab-content');

    tabButtons.forEach(button => {
      button.addEventListener('click', function() {
        const targetTab = this.getAttribute('data-tab');

        // Remove active class from all buttons and contents
        tabButtons.forEach(btn => btn.classList.remove('active'));
        tabContents.forEach(content => content.classList.remove('active'));

        // Add active class to clicked button and corresponding content
        this.classList.add('active');
        const targetContent = document.querySelector(`[data-tab="${targetTab}"].sage-tab-content`);
        if (targetContent) {
          targetContent.classList.add('active');
        }

        // Smooth scroll to content (non-sticky version)
        setTimeout(function() {
          const navBar = document.getElementById('sageTabNav');
          if (navBar) {
            // Scroll to the top of the nav bar, with a 20px buffer
            const navTop = navBar.getBoundingClientRect().top + window.pageYOffset - 20;
            window.scrollTo({ top: navTop, behavior: 'smooth' });
          }
        }, 50);
      });
    });

    // --- STICKY NAVIGATION CODE REMOVED ---

    // Animated Counter for Stats
    function animateCounter(element) {
      const target = parseInt(element.getAttribute('data-count'));
      const duration = 2000; // 2 seconds
      const increment = target / (duration / 16); // 60fps
      let current = 0;

      const timer = setInterval(function() {
        current += increment;
        if (current >= target) {
          element.textContent = target;
          clearInterval(timer);
        } else {
          element.textContent = Math.floor(current);
        }
      }, 16);
    }

    // Intersection Observer for Counter Animation
    const statsObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          const counters = entry.target.querySelectorAll('.sage-stat-value[data-count]');
          counters.forEach(function(counter) {
            animateCounter(counter);
          });
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.5 });

    const quickStats = document.querySelector('.sage-quick-stats');
    if (quickStats) {
      statsObserver.observe(quickStats);
    }

    // Lightbox Functionality
    const lightbox = document.getElementById('sageLightbox');
    const lightboxImg = lightbox.querySelector('.sage-lightbox-img');
    const lightboxClose = lightbox.querySelector('.sage-lightbox-close');
    const lightboxPrev = lightbox.querySelector('.sage-lightbox-prev');
    const lightboxNext = lightbox.querySelector('.sage-lightbox-next');
    let currentImageIndex = 0;
    const galleryImages = Array.from(document.querySelectorAll('.sage-gallery-item img'));
    const galleryItems = document.querySelectorAll('.sage-gallery-item');

    galleryItems.forEach(function(item, index) {
      item.addEventListener('click', function() {
        currentImageIndex = index;
        openLightbox(galleryImages[index].src);
      });
    });

    function openLightbox(src) {
      lightboxImg.src = src;
      lightbox.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeLightbox() {
      lightbox.classList.remove('active');
      document.body.style.overflow = '';
    }

    lightboxClose.addEventListener('click', closeLightbox);
    lightbox.addEventListener('click', function(e) {
      if (e.target === lightbox) {
        closeLightbox();
      }
    });

    lightboxPrev.addEventListener('click', function() {
      currentImageIndex = (currentImageIndex - 1 + galleryImages.length) % galleryImages.length;
      lightboxImg.src = galleryImages[currentImageIndex].src;
    });

    lightboxNext.addEventListener('click', function() {
      currentImageIndex = (currentImageIndex + 1) % galleryImages.length;
      lightboxImg.src = galleryImages[currentImageIndex].src;
    });

    // Keyboard navigation for lightbox
    document.addEventListener('keydown', function(e) {
      if (!lightbox.classList.contains('active')) return;

      if (e.key === 'Escape') closeLightbox();
      if (e.key === 'ArrowLeft') lightboxPrev.click();
      if (e.key === 'ArrowRight') lightboxNext.click();
    });

    // Simple AOS (Animate On Scroll) Implementation
    const animatedElements = document.querySelectorAll('[data-aos]');

    const aosObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('sage-aos-animate');
        }
      });
    }, { threshold: 0.1 });

    animatedElements.forEach(function(el) {
      aosObserver.observe(el);
    });

  })();
});
